V.CompensationRules = {
  ["DRUID"] = {
    { id="DRU_COMP_08", minL=10, maxL=60, cat="RACIAL_ADVANTAGE", cond="Race == Tauren (Endurance +5% Total HP & +2% Crit Bonus + War Stomp 2s AoE Stun) OR Night Elf (+2% Dodge & Shadowmeld)", free="Brutal Impact (104940) (when Tauren War Stomp already provides an AoE interrupt/stun for healing casts)", shift="Sharpened Claws (104945) (+6% Feral Crit) + Predatory Strikes (104952)", gain="6.8", why="Tauren War Stomp lets you shift out of Bear/Cat, stun up to 5 mobs for 2s, cast Regrowth + Rejuvenation, and shift right back before taking a hit!" },
    { id="DRU_COMP_02", minL=20, maxL=39, cat="CONSUMABLE_ELIXIR", cond="Outdoor Questing (Before Level 40 Mount — Cat Form +30% Speed via Feral Swiftness 2/2)", free="Indoor-only filler talents", shift="Feral Swiftness (104941) (2/2 = +30% Cat Outdoor Speed & +4% Dodge!) + Ferocity (104938) (5/5)", gain="18.0", why="Between Levels 20 and 30 (before Travel Form unlocks at 30), Feral Swiftness (2/2) turns Cat Form into a 130% speed mount that stays in stealth/combat posture, cutting travel time across Azeroth by 23%!" },
    { id="DRU_COMP_03", minL=30, maxL=60, cat="GEAR_MILESTONE", cond="Equipped High-Armor Leather (Warden Staff / Ring of Protection / Devotion Aura) in Dire Bear Form (+360% Armor)", free="Thick Hide (104942) (Once Armor exceeds 65% mitigation in 5-man dungeons)", shift="Primal Fury (104952) (+5 Rage on Crit!) + Primal Bite/Mangle (104949) + Savage Fury (104946)", gain="11.7", why="Dire Bear Form already multiplies leather armor by 460%! Once dungeon leather puts you over 60% mitigation, shifting points from Thick Hide into Primal Fury + Primal Bite (Mangle) generates massive Rage and threat." },
    { id="DRU_COMP_04", minL=30, maxL=60, cat="PARTY_COOP_BUFF", cond="Active Innervate + Blessing of Wisdom / Mana Spring Totem", free="Moonglow (104925) (3/3 = -9% Spell Mana)", shift="Nature's Grace (104934) (-0.5s Cast Time on Crit!) + Vengeance (104932) (+100% Crit Bonus!) + Eclipse (104935)", gain="13.9", why="When external mana buffs + Innervate solve Balance mana consumption, shifting 3 points from Moonglow into Nature's Grace + Eclipse + Vengeance maximizes Starfire and Wrath crit chains." },
    { id="DRU_COMP_06", minL=30, maxL=60, cat="PARTY_COOP_BUFF", cond="Fighting Bleed-Immune Undead/Elemental/Mechanical Mobs vs. Bleed-Vulnerable Beasts/Humanoids", free="Rend and Tear (104953) (on Bleed-Immune Mechanicals/Elementals)", shift="Shredding Attacks (104948) (-18 Energy Shred!) + Naturalist (104957) (+10% All Physical Damage!)", gain="9.6", why="Against bleed-vulnerable targets, Primal Bite (Mangle) +30% bleed debuff + Rend and Tear (+20% Ferocious Bite crit on bleeding targets) is king; against bleed-immune targets, direct Shred + Naturalist (+10% Physical) compensates." },
    { id="DRU_COMP_07", minL=30, maxL=60, cat="GEAR_MILESTONE", cond="High +Healing Gear + Gift of the Earthmother (104918) + Swiftmend (104912)", free="Improved Tranquility (104914)", shift="Gift of the Earthmother (104918) + Improved Rejuvenation (104917) + Wild Growth (104910)", gain="14.1", why="Forever's [Gift of the Earthmother] reduces Rejuvenation GCD by 0.5s and boosts periodic haste by 10%, turning Rejuvenation + Swiftmend + Wild Growth into an instant mobile healing machine." },
    { id="DRU_COMP_01", minL=40, maxL=60, cat="GEAR_MILESTONE", cond="Equipped Wolfshead Helm (Item 8345, Req Lv 40 Leatherworking: +20 Energy on Cat Form Shift!)", free="Thick Hide (104942) / Feral Instinct (when pure Cat DPS)", shift="Furor (104958) (5/5 = +40 Energy) + Natural Shapeshifter (104920) (3/3 = -30% Shift Mana) + Shifting Power (104951)", gain="26.4", why="THE ULTIMATE COMPENSATION SYNERGY: Wolfshead Helm (+20 Energy) + Furor 5/5 (+40 Energy) grants 60 Energy the instant you shift into Cat Form! Shifting those 4 points into Natural Shapeshifter (3/3) + Shifting Power (1/1) lets you Powershift after every Ferocious Bite/Rip for +26.4% sustained DPS!" },
    { id="DRU_COMP_05", minL=40, maxL=60, cat="GEAR_MILESTONE", cond="Carried 2 Gear Sets in Bags (Feral Agi/Str Set + Intellect/Spirit Healer Set) with Heart of the Wild (5/5)", free="Single-role Row 7 Capstone (Berserk / Wild Growth)", shift="Heart of the Wild (104939) (5/5 = +20% Intellect, +20% Bear Stamina, +10% Cat AP!) + Nature's Swiftness (104921)", gain="15.5", why="A 0/30/21 Heart of the Wild + Nature's Swiftness build lets you Tank dungeons in Bear gear (+20% Stamina), DPS in Cat gear (+10% AP), and main-heal dungeons in Intellect gear (+20% Total Intellect) WITHOUT paying a trainer a single copper to respec!" },
  },
  ["HUNTER"] = {
    { id="HUN_COMP_03", minL=10, maxL=60, cat="GEAR_MILESTONE", cond="Tamed Fast 1.20s-1.30s Attack Speed Cat/Raptor/Wind Serpent Pet", free="Improved Aspect of the Monkey (104974)", shift="Ferocity (104967) (+10% Pet Crit) + Frenzy (104962) (100% Pet +30% Haste Uptime!)", gain="12.9", why="A fast 1.20s attack speed pet with Ferocity (5/5) lands critical strikes every 3-4 seconds, keeping Frenzy (+30% Pet Attack Speed) at 98% uptime and causing massive spell pushback on enemy casters." },
    { id="HUN_COMP_08", minL=10, maxL=60, cat="RACIAL_ADVANTAGE", cond="Race == Troll (Berserking Haste + Bow Spec) OR Dwarf (Gun Spec) OR Orc (Command Pet Damage)", free="Hawk Eye (105013) (when fighting in tight indoor corridors <= 30 yds)", shift="Rapid Killing (105005) + Rapid Recuperation (104999)", gain="7.4", why="Pairing Troll Berserking + Rapid Fire with Rapid Killing and Rapid Recuperation restores massive Mana and haste after every mob kill." },
    { id="HUN_COMP_02", minL=14, maxL=60, cat="PARTY_COOP_BUFF", cond="Active Blessing of Wisdom + Mana Spring Totem OR High-Spirit / Aspect of the Viper Sustain", free="Efficiency (105009) (5/5 = -10% Shot/Sting Mana Cost)", shift="Lethal Shots (105011) (+5% Ranged Crit) + Improved Arcane Shot / Aimed Shot", gain="8.3", why="External mana regeneration (Blessing of Wisdom / Mana Spring) eliminates Hunter mana dry-outs, allowing 5 points in Efficiency to shift straight into Lethal Shots (+5% Crit) and Rapid Killing." },
    { id="HUN_COMP_04", minL=15, maxL=60, cat="MOB_LEVEL_HIT_CAP", cond="Equipped +3% Scope/Gear Hit OR Fighting Same-Level / Green Mobs", free="Surefooted (104987) (when kiting is not required)", shift="Savage Strikes (104993) (+20% Raptor Strike/Mongoose Crit) + Clever Traps (104991)", gain="6.5", why="When Ranged Hit is already capped via scopes/gear against leveling mobs, points in Surefooted can shift into Savage Strikes for melee-weave burst or Marksmanship damage." },
    { id="HUN_COMP_01", minL=20, maxL=60, cat="PARTY_COOP_BUFF", cond="Grouped with Tank Partner (Warrior/Paladin/Bear holds 100% aggro — no Pet Tank needed!)", free="Endurance Training (104976) / Thick Hide / Improved Mend Pet (104968)", shift="Lone Wolf (105007) (+15% All Damage without Pet!) OR Mortal Shots (105002) + Ranged Weapon Spec (104998)", gain="14.8", why="In a duo or dungeon group where a Tank holds aggro, dismissing your pet and investing 1 point in Forever's [Lone Wolf (105007)] grants an instant flat +15% Ranged and Melee damage multiplier while freeing all pet survivability points!" },
    { id="HUN_COMP_05", minL=20, maxL=60, cat="WEAPON_SPEED_SYNC", cond="Equipped Slow Ranged Bow/Gun/Crossbow (Speed >= 2.90s, e.g. Bow of Searing Arrows, Sniper Rifle)", free="Improved Stings (105008) [on fast-dying solo mobs < 10 sec]", shift="Careful Aim (105006) + Mortal Shots (105002) + Sniper Shot (104997)", gain="10.7", why="On solo mobs that die in 7-9 seconds, Serpent Sting loses half its ticks; a slow >=2.90s ranged weapon maximizes Multi-Shot and Sniper Shot instant weapon-damage multipliers without breaking Auto-Shot clipping." },
    { id="HUN_COMP_07", minL=20, maxL=60, cat="CONSUMABLE_ELIXIR", cond="Minor Speed Boot Enchant Active (Indoor Dungeon Runs where Aspect of the Cheetah is Daze-Risky)", free="Pathfinding (104973) (+6% Aspect of Cheetah/Pack Speed)", shift="Focused Fire (104975) (+2% All Damage while Pet Active) + Unleashed Fury (104969)", gain="5.8", why="Inside dungeons where Aspect of the Hawk is kept on 100% of the time, shifting 2 points from Pathfinding into Focused Fire gives a permanent +2% damage multiplier." },
    { id="HUN_COMP_06", minL=30, maxL=60, cat="CONSUMABLE_ELIXIR", cond="Stacked Agility Gear (>250 Agility) + Elixir of Greater Agility + Grace of Air Totem", free="Survivalist (104992) (+10% Stamina)", shift="Lightning Reflexes (110859) (+10% Total Agility!) + Expose Prey (104985)", gain="11.2", why="Lightning Reflexes scales multiplicatively with all flat Agility from gear, Elixirs, and Grace of Air Totem, converting high Agility directly into Ranged AP, Melee AP, Crit, and Dodge." },
  },
  ["MAGE"] = {
    { id="MAG_COMP_05", minL=10, maxL=22, cat="GEAR_MILESTONE", cond="Equipped High-DPS Wand (Levels 10-22) Before Spell Power Gear Exists", free="High-mana Arcane Missiles spam", shift="Wand Specialization (105691) (2/2 = +25% Wand Damage) + Improved Frostbolt (105674)", gain="16.0", why="Opening with 2-3 Frostbolts and finishing the last 25% of mob HP with a +25% Wand Spec wand starts your 5-Second Rule mana tick 4 seconds before the mob dies, cutting drinking downtime by 60%." },
    { id="MAG_COMP_08", minL=10, maxL=60, cat="RACIAL_ADVANTAGE", cond="Race == Gnome (Expansive Mind +5% Total Intellect & Escape Artist) OR Undead (Cannibalize + WotF)", free="Magic Absorption (105689)", shift="Arcane Mind (105678) (+15% Intellect stacks multiplicatively with Gnome +5% Intellect!)", gain="6.7", why="Gnome's +5% Intellect racial multiplies with Arcane Mind (+15% Intellect) and Blessing of Kings (+10% Stats) for a massive Mana pool and Spell Crit boost." },
    { id="MAG_COMP_02", minL=14, maxL=60, cat="MOB_LEVEL_HIT_CAP", cond="Elemental Precision (105673) (3/3 = +6% Fire & Frost Hit) vs. Same-Level Solo Mobs", free="+Spell Hit Green/Blue Gear Slots", shift="Equip Pure +Frost/+Fire Spell Damage Gear ('of Frozen Wrath' / 'of Fiery Wrath') + Ice Shards (105672)", gain="11.5", why="3/3 Elemental Precision grants +6% Spell Hit to both Frost and Fire, which COMPLETELY caps your spell hit (99%) against mobs up to +2 levels above you! That compensates for 100% of gear hit requirements while leveling, letting you wear pure 'of Frozen/Fiery Wrath' damage gear!" },
    { id="MAG_COMP_01", minL=20, maxL=60, cat="MOB_LEVEL_HIT_CAP", cond="Open-World AoE Blizzard Farming (5-12 Melee Mobs at once — Frostbite roots break clump grouping!)", free="Frostbite (105669) (0/3 MUST BE OFF for AoE Blizzard!) + Ice Shards (Blizzard cannot crit!)", shift="Improved Blizzard (105664) (3/3 = 65% Chill Slow!) + Permafrost (105671) (3/3) + Piercing Ice (105668) + Frost Channeling (105667)", gain="28.0", why="CRITICAL COMPENSATION: Blizzard ticks cannot crit, and if Frostbite (15% root proc) freezes 1 mob out of a 10-mob pack, the pack splits and ruins your AoE cone! For AoE Blizzard farming, keep Frostbite at 0/3 and max Improved Blizzard + Permafrost (75% slow). For Single-Target/Shatter leveling, swap 3/3 Improved Blizzard INTO Frostbite (3/3) + Ice Shards (5/5) + Shatter (5/5)!" },
    { id="MAG_COMP_03", minL=20, maxL=60, cat="PARTY_COOP_BUFF", cond="Conjured Mana Gem (Agate/Jade/Citrine/Ruby) + Evocation + Mage Armor + Blessing of Wisdom", free="Arcane Meditation (105681) / Frost Channeling (if single-target bursting)", shift="Arcane Concentration (105688) (Clearcasting!) + Ice Lance (110862) + Fingers of Frost (110845)", gain="10.4", why="Combining Conjured Mana Gems, Evocation, and Clearcasting (10% free spell proc) eliminates mana starvation during boss and multi-mob pulls." },
    { id="MAG_COMP_04", minL=25, maxL=60, cat="GEAR_MILESTONE", cond="Spell Crit >= 20% (via Intellect/Crit Gear + Molten Armor / Moonkin Aura + Critical Mass 3/3)", free="Flame Throwing / Improved Fire Ward", shift="Ignite (105653) (5/5 = +40% Crit Burn) + Heating Up (105644) (Instant Pyroblast!) + Master of Elements (105643)", gain="18.2", why="Once Fire Crit crosses 20%, Forever's [Heating Up] (2 crits in a row = instant, 50%-cheaper Pyroblast) + Ignite (+40% burn) + Master of Elements (30% mana refund) creates explosive zero-cast-time chains." },
    { id="MAG_COMP_06", minL=30, maxL=60, cat="GEAR_MILESTONE", cond="High Intellect & Spirit Gear + Arcane Blast (110847) + Missile Barrage (110848)", free="Arcane Shielding (105683)", shift="Arcane Blast (110847) + Missile Barrage (110848) + Arcane Mind (105678) + Arcane Power (105676)", gain="14.9", why="Stacking Arcane Blast 2-3 times to trigger a fast, free Missile Barrage Arcane Missiles volley delivers top-tier single-target dungeon/raid DPS." },
    { id="MAG_COMP_07", minL=30, maxL=60, cat="GEAR_MILESTONE", cond="Fingers of Frost (110845) + Ice Lance (110862) + Shatter (105661) (5/5 = +50% Crit vs Frozen!)", free="Winter's Chill (105658) [during solo leveling where mobs die in 3 casts]", shift="Shatter (105661) + Fingers of Frost (110845) + Ice Lance (110862) + Ice Shards (105672)", gain="17.6", why="While soloing, mobs die in 3 casts so Winter's Chill (5 stacks) never stacks up—whereas Fingers of Frost treats chilled targets as Frozen, giving Frostbolt + Ice Lance a +50% Shatter crit bonus and 3x Ice Lance damage!" },
  },
  ["PALADIN"] = {
    { id="PAL_COMP_06", minL=10, maxL=60, cat="RACIAL_ADVANTAGE", cond="Race == Undead (Forever Paladin: Cannibalize + Touch of the Grave) OR Race == Human (+Weapon Skill)", free="Precision (105638) (if Human Sword/Mace skill active vs same-level mobs)", shift="Guardian's Favor (105637) / Toughness (105626) / Improved Holy Strike (105333)", gain="6.9", why="Weapon skill racials reduce glancing blow penalties and miss rates, compensating for Precision while leveling." },
    { id="PAL_COMP_02", minL=14, maxL=60, cat="PARTY_COOP_BUFF", cond="Active Self/Party Blessing of Wisdom + Shaman Mana Spring Totem + Lesser Mana Oil", free="Benediction (105706) (-15% Seal/Judgement Mana)", shift="Deflection (105707) (+5% Parry -> faster parry-haste swings!) OR Divine Strength (105639)", gain="7.8", why="When Blessing of Wisdom + Mana Spring Totem + Judgement of Wisdom already keep Mana above 80%, Benediction's mana discount saves 0 seconds of drinking downtime. Shifting 5 points into Deflection (+5% Parry) grants parry-haste extra melee swings and reduces damage taken!" },
    { id="PAL_COMP_05", minL=18, maxL=60, cat="CONSUMABLE_ELIXIR", cond="Minor Speed Boot Enchant (+8% Run Speed) ALREADY Equipped", free="Pursuit of Justice (105699) (2/2 = +8% Movement Speed — does NOT stack with Minor Speed boot enchant!)", shift="Vindication (105702) / Sanctified Judgement (105701)", gain="6.4", why="If your boots already have Minor Speed Enchant (or you shift Pursuit of Justice ON and enchant boots with +7 Agility/+7 Stamina instead!), you avoid overlapping non-stacking movement speed buffs and gain free combat stats or 2 talent points!" },
    { id="PAL_COMP_01", minL=20, maxL=60, cat="WEAPON_SPEED_SYNC", cond="Equipped Slow 2H Weapon (Speed >= 3.50s, e.g. Verigan's Fist 6953 at L20, Corpsemaker 6687 at L29)", free="Divine Strength (105639) [Early Dip]", shift="Seal of Command (105696) + Conviction (105703) + Two-Handed Weapon Specialization (105697)", gain="14.5", why="Seal of Command uses a 7 PPM (Procs Per Minute) formula: a 3.80s weapon has a 44.3% proc rate per swing and hits for 70% of massive top-end weapon damage, making Seal of Command + Conviction (5/5) mandatory the instant Verigan's Fist is acquired." },
    { id="PAL_COMP_03", minL=25, maxL=60, cat="GEAR_MILESTONE", cond="Equipped Thorium/Mithril Shield Spike + Blessing of Sanctuary + Retribution Aura (AoE Multi-Mob Pulls)", free="Anticipation (105636) (-Crit chance -> fewer Redoubt/Reckoning procs when solo!)", shift="Redoubt (105630) + Shield Specialization (110874) + Reckoning (105627)", gain="12.6", why="For solo AoE farming (3-6 mobs), having TOO much Defense skill (Anticipation 5/5) actually REDUCES how often mobs crit you to trigger Redoubt (+30% Block) and Reckoning (extra swings)! Letting mobs trigger Redoubt/Reckoning with a Shield Spike attached melts packs." },
    { id="PAL_COMP_04", minL=30, maxL=60, cat="GEAR_MILESTONE", cond="Equipped +Spell Crit / High-Intellect Gear (>= 18% Holy Spell Crit)", free="Improved Blessing of Wisdom (105335)", shift="Illumination (105329) (5/5 = 100% Mana Refund on Holy Crits!) + Holy Power (105321)", gain="13.2", why="Once Holy Crit reaches 18%+, Illumination (5/5) + Holy Power (+5% Holy Crit) refunds 100% of the base mana cost on every critical Flash of Light, Holy Light, or Holy Shock, creating infinite mana sustain." },
    { id="PAL_COMP_07", minL=35, maxL=60, cat="PARTY_COOP_BUFF", cond="Grouped with Shaman (Windfury Totem + Grace of Air Totem) in Cross-Faction Forever Party", free="Eye for an Eye (105698)", shift="Vengeance (105693) (3/3 = +15% Physical & Holy Damage on Crit) + Sacred Arbiter (105700)", gain="15.1", why="Windfury Totem extra swings + Grace of Air Agility Crit keep Vengeance (+15% all Physical and Holy damage) at 95%+ uptime and proc Sacred Arbiter instant heals continuously." },
    { id="PAL_COMP_08", minL=40, maxL=60, cat="GEAR_MILESTONE", cond="Equipped Spell Damage Plate/Mail + Fast 1.50s-1.80s 1H Weapon (Seal of Righteousness SP Scaling)", free="Two-Handed Weapon Specialization (105697)", shift="Holy Shock (105323) + Infusion of Light (110871) + Improved Seals (105334)", gain="11.4", why="When stacking Spell Damage gear with a fast 1H weapon + Shield, Seal of Righteousness + Holy Shock + Exorcism outscales slow physical 2H swings while granting full shield armor." },
  },
  ["PRIEST"] = {
    { id="PRI_COMP_01", minL=10, maxL=26, cat="GEAR_MILESTONE", cond="Equipped High-DPS Wand (e.g. Lesser Magic Wand L5, Greater Magic Wand L13, Gravestone Scepter L18)", free="High-mana cast-time talents before Level 24", shift="Wand Specialization (105850) (2/2 = +25% Wand Damage) + Spirit Tap (105833) (5/5 = +100% Spirit on kill)", gain="24.5", why="Between Levels 10 and 24, a high-DPS Wand + Wand Specialization (2/2 in Forever!) deals more DPS than Mind Blast/Smite spam while keeping you inside the 5-Second Rule (FSR) for 100% Spirit mana regeneration." },
    { id="PRI_COMP_03", minL=10, maxL=60, cat="RACIAL_ADVANTAGE", cond="Race == Undead (Cannibalize 35% HP/35% Mana + Touch of the Grave + Devouring Plague)", free="Improved Renew (105866) / Mental Agility (105842)", shift="Improved Shadow Word: Pain (105830) + Shadow Weaving (105821) + Devouring Contagion (105819)", gain="9.3", why="Undead Cannibalize in WoW Forever regenerates BOTH 35% Health and 35% Mana over 10s, compensating for healing mana costs and synergizing with Devouring Plague + Forever's Devouring Contagion talent." },
    { id="PRI_COMP_06", minL=15, maxL=60, cat="MOB_LEVEL_HIT_CAP", cond="Solo Grinding Same-Level Mobs (4% Spell Miss) vs. Dungeon Orange Bosses (16% Spell Miss)", free="Shadow Focus (110851) (reduce from 5/5 to 2/5 when fighting green/same-level solo mobs)", shift="Blackout (105832) (Stun proc on Shadow spells) OR Improved Mind Blast (105827)", gain="6.2", why="Against same-level mobs, 2/5 Shadow Focus (+4% Shadow Hit) already hits the 99% spell hit cap! The remaining 3 points in Shadow Focus are wasted unless you are fighting +2/+3 level elites." },
    { id="PRI_COMP_02", minL=20, maxL=60, cat="PARTY_COOP_BUFF", cond="Dungeon / Raid Group Where Teammates Get 75%+ of Killing Blows (Spirit Tap rarely procs!)", free="Spirit Tap (105833) (requires landing the killing blow!)", shift="Meditation (105837) (5/5 in Forever) + Shadow Focus (110851) + Darkness (105818)", gain="11.9", why="CRITICAL COMPENSATION: Spirit Tap (5/5) is the #1 solo talent in the game, but ONLY triggers if YOU land the killing blow! In a 5-man dungeon or raid where DPS teammates get the killing blows, shifting 5 points out of Spirit Tap into Meditation (in-combat casting regen) and Darkness (+10% Shadow damage) gains +11.9% sustained output!" },
    { id="PRI_COMP_08", minL=20, maxL=60, cat="CONSUMABLE_ELIXIR", cond="Power Word: Shield Active Before Pulling (100% Pushback Immunity while Shield Holds!)", free="Martyrdom / Blessed Recovery", shift="Improved Power Word: Shield (105846) + Divine Fury (105863) + Searing Light (105858)", gain="7.9", why="Because Power Word: Shield completely prevents spell pushback while active, buffing Improved PW:S (3/3) + Soul Warding compensates for spell pushback talents during solo pulls." },
    { id="PRI_COMP_05", minL=30, maxL=60, cat="GEAR_MILESTONE", cond="High-Spirit Gear (>= 200 Spirit) + Blessing of Kings (+10% Stats)", free="Mental Strength (105835) (Flat Max Mana %)", shift="Spiritual Guidance (105853) (5/5 = +25% of Total Spirit added to Spell Damage & Healing!) + Penance (105834)", gain="13.4", why="With high Spirit gear, Spiritual Guidance converts 25% of your total Spirit directly into BOTH Healing Power AND Spell Damage, turning Spirit into a dual-purpose sustain + throughput stat." },
    { id="PRI_COMP_04", minL=40, maxL=60, cat="GEAR_MILESTONE", cond="Equipped Shadoweave Set / +Shadow Spell Damage Gear (>= +120 Shadow Power) at Level 40+", free="Wand Specialization (105850) [via Level 40 Trainer Respec]", shift="Shadowform (105817) + Darkness (105818) + Mind Flay (105826) + Shadow Weaving (105821)", gain="19.8", why="Once you equip Shadoweave pieces and hit Level 40, Mind Flay + Shadow Word: Pain scaled by Shadowform (+15% Shadow) and Shadow Weaving (+15% Shadow) outscales wanding by nearly 2x—triggering our Level 40 Trainer Respec!" },
    { id="PRI_COMP_07", minL=40, maxL=60, cat="PARTY_COOP_BUFF", cond="Paired with Mage / Warlock / Elemental Shaman Caster Partner", free="Solo smite filler talents", shift="Power Infusion (105836) + Soul Warding (105839) + Penance (105834) + Divine Aegis (105840)", gain="15.6", why="Injecting Power Infusion (+20% Spell Damage/Haste) into a geared Caster partner during cooldown windows multiplies duo kill speed while Soul Warding + Penance keeps both players immortal." },
  },
  ["ROGUE"] = {
    { id="ROG_COMP_07", minL=10, maxL=60, cat="CONSUMABLE_ELIXIR", cond="Active Elixir of the Mongoose / Greater Agility + Leader of the Pack (+8% Total Crit)", free="Remorseless Attacks (105723) [during Dungeon Boss Fights with no adds]", shift="Malice (105722) + Seal Fate (105710) + Restless Blades (108100)", gain="10.2", why="Remorseless Attacks is god-tier for solo chain-killing (+40% crit after each kill), but on single-target dungeon bosses with no adds, shifting those 2 points into permanent crit/cooldown reduction wins." },
    { id="ROG_COMP_03", minL=15, maxL=60, cat="CONSUMABLE_ELIXIR", cond="Stocked Thistle Tea (100 Energy Instant Restore) + Relentless Strikes (105759)", free="Vigor (105718)", shift="Lethality (105716) (+30% Crit Damage Bonus!) + Ruthlessness (105721)", gain="8.9", why="Relentless Strikes (25 Energy refund on 5-CP finishers) + Thistle Tea covers burst Energy windows, allowing points in Vigor to shift into Lethality (+30% crit strike damage bonus)." },
    { id="ROG_COMP_04", minL=16, maxL=60, cat="PARTY_COOP_BUFF", cond="Soloing Multiple Melee Mobs (No Tank) vs. Grouped with Tank (Backstab/Behind Target 100%)", free="Deflection (105738) + Riposte (105735) [WHEN Tank holds aggro — you cannot Parry from behind!]", shift="Precision (105737) + Puncturing Wounds (105719) / Aggression (105730)", gain="9.8", why="CRITICAL COMPENSATION: Riposte is S-Tier when soloing (mobs attack your front, triggering Parry -> 150% weapon damage + disarm for 10 Energy). The moment you group with a Tank and attack from behind, mobs NEVER attack you—so shifting 4 points out of Deflection/Riposte into Precision/Aggression gains +9.8% pure DPS!" },
    { id="ROG_COMP_02", minL=20, maxL=60, cat="WEAPON_SPEED_SYNC", cond="Equipped Slow Main-Hand Sword/Mace (2.60s-2.80s) + Fast Off-Hand (1.40s-1.50s) + Windfury Totem", free="Dagger/Fist talents", shift="Hack and Slash (105727) + Dual Wield Specialization (105740) + Blade Flurry (105728)", gain="13.7", why="A slow 2.70s Main-Hand Sword maximizes Sinister Strike and extra-swing damage from Hack and Slash (5% extra swing chance) and Windfury Totem, while a fast 1.40s Off-Hand applies poisons rapidly." },
    { id="ROG_COMP_06", minL=20, maxL=60, cat="PARTY_COOP_BUFF", cond="Warrior Partner Applying 5x Sunder Armor + Druid Faerie Fire", free="Improved Expose Armor (105717) / Serrated Blades (105752)", shift="Murder (105720) + Improved Slice and Dice (105739)", gain="8.1", why="When a Warrior/Druid partner already strips enemy armor to near-zero, Improved Expose Armor is redundant—keep 100% Slice and Dice uptime instead." },
    { id="ROG_COMP_05", minL=22, maxL=60, cat="RACIAL_ADVANTAGE", cond="Race == Night Elf (Shadowmeld +Stealth Level) OR Boots Enchanted with Stealth", free="Master of Deception (105761)", shift="Opportunity (105756) (+20% Backstab/Ambush/Garrote/Mutilate Damage!) + Camouflage (105760)", gain="7.5", why="Night Elf Shadowmeld passive stealth bonus and stealth gear already prevent same-level mobs from spotting you, freeing 3 points from Master of Deception to max Opportunity (+20% opener damage)." },
    { id="ROG_COMP_01", minL=30, maxL=60, cat="GEAR_MILESTONE", cond="Equipped Dual Daggers + Instant/Deadly Poisons Applied to Both Weapons", free="Improved Sinister Strike (105741)", shift="Mutilate (105709) + Vile Poisons (105713) + Seal Fate (105710) + Venom (105712)", gain="16.4", why="Once dual Daggers and Poisons are active at Level 30+, Forever's [Mutilate] strikes with both daggers simultaneously, deals +20% damage to poisoned targets, and awards 2-3 combo points per cast when paired with Seal Fate!" },
    { id="ROG_COMP_08", minL=30, maxL=60, cat="WEAPON_SPEED_SYNC", cond="Equipped Slow 2.70s+ Main-Hand Fist/Mace/Sword for Hemorrhage (105748)", free="Improved Ambush (105755)", shift="Hemorrhage (105748) + Sinister Calling / Cutthroat (105750) + Thousand Cuts (110866)", gain="12.1", why="Hemorrhage costs only 35 Energy and scales with raw main-hand weapon damage without requiring a Dagger or standing behind the target." },
  },
  ["SHAMAN"] = {
    { id="SHA_COMP_06", minL=10, maxL=60, cat="RACIAL_ADVANTAGE", cond="Race == Orc (Savage +1% All Melee & Spell Crit + Blood Fury +10% AP & SP) OR Tauren (War Stomp +5% HP)", free="Eye of the Storm (104767) [when Tauren War Stomp + Earthbind kites melee]", shift="Elemental Devastation (104771) (+9% Melee Crit after Spell Crit!) + Thundering Strikes (104815)", gain="8.6", why="Orc's custom Forever racial [Savage] grants +1% to BOTH Melee AND Spell Crit, creating a permanent feedback loop between Elemental Devastation and Flurry." },
    { id="SHA_COMP_05", minL=15, maxL=60, cat="GEAR_MILESTONE", cond="Equipped Fast 1.50s-1.80s Dagger/Mace + Flametongue/Rockbiter + High-Armor Shield (Solo Elite / Tanking)", free="Two-Handed burst talents", shift="Earth's Grasp / Guardian Totems (104812) + Toughness (104805) + Spirit Weapons (104802) (Parry!)", gain="10.4", why="With a Shield equipped (~45% total Physical mitigation), a fast 1.60s 1H weapon procs Maelstrom Weapon and Flametongue rapidly while Spirit Weapons adds Parry mitigation." },
    { id="SHA_COMP_08", minL=16, maxL=60, cat="CONSUMABLE_ELIXIR", cond="Minor Wizard Oil / Brilliant Wizard Oil Applied to Weapon + Fire Power Elixir", free="Elemental Warding (104774)", shift="Trial by Fire / Improved Fire Nova (104768) + Call of Thunder (104766)", gain="7.3", why="Wizard Oil spell damage boosts every pulse of Magma/Fire Nova Totem and Flame Shock." },
    { id="SHA_COMP_01", minL=20, maxL=60, cat="PARTY_COOP_BUFF", cond="Water Shield (408510) Unlocked OR Active Blessing of Wisdom + Mana Spring Totem", free="Convection (104775) (-10% Shock/Bolt Mana) / Tidal Focus (104789)", shift="Concussion (104776) (+5% Bolt/Shock Damage) + Call of Flame (104773) + Reverberation (104772)", gain="11.2", why="When Water Shield (or Co-Op Blessing of Wisdom + Mana Spring) refunds mana every time a mob hits you, Convection's mana discount is redundant—shifting 5 points into Concussion/Reverberation adds pure DPS." },
    { id="SHA_COMP_04", minL=20, maxL=60, cat="GEAR_MILESTONE", cond="Equipped High-Attack Power Gear + Mental Dexterity (110863) + Mental Quickness (110865)", free="Pure Intellect/Spell Power caster items", shift="Mental Dexterity (110863) + Mental Quickness (110865) + Maelstrom Weapon (110864)", gain="14.2", why="Forever's Mental Dexterity and Mental Quickness convert your Attack Power directly into Spell Power, meaning pure Strength/Agility/AP gear simultaneously powers up your Shocks, Maelstrom instant Lightning Bolts, and self-heals!" },
    { id="SHA_COMP_02", minL=30, maxL=60, cat="WEAPON_SPEED_SYNC", cond="Equipped Slow 2H Axe/Mace (Speed >= 3.50s, e.g. Corpsemaker, Ravager) + Windfury Weapon (Lv 30)", free="Shield Specialization / Anticipation", shift="Elemental Weapons (104810) (+20% Windfury AP Bonus!) + Flurry (104804) + Stormstrike (104801)", gain="17.5", why="At Level 30 when Windfury Weapon unlocks, pairing a slow >=3.50s 2H weapon with Elemental Weapons (3/3) and Stormstrike creates devastating triple-hit Windfury crits." },
    { id="SHA_COMP_07", minL=30, maxL=60, cat="PARTY_COOP_BUFF", cond="5-Man Dungeon / Raid Healing with Paladin Blessing of Wisdom", free="Totemic Focus (104783) (when stationary totems aren't re-dropped every 15s)", shift="Riptide (104777) + Healing Way (104780) + Purification (104778) + Tidal Mastery (104793)", gain="12.8", why="Riptide's instant HoT + Chain Heal / Healing Way synergy provides unmatched burst and multi-target dungeon healing." },
    { id="SHA_COMP_03", minL=40, maxL=60, cat="GEAR_MILESTONE", cond="Flame Shock Active on Target + Lava Burst (408490) Unlocked at Level 40", free="Early Enhancement melee filler (via Level 40 Trainer Respec)", shift="Lava Burst (104760) + Elemental Fury (104769) (+100% Crit Damage Bonus!) + Lightning Overload (104763)", gain="21.3", why="Lava Burst ALWAYS critically strikes when Flame Shock is on the target! Pairing that 100% guaranteed crit with Elemental Fury (doubling crit bonus damage to 200%) turns every 8s Lava Burst into a massive nuke." },
  },
  ["WARLOCK"] = {
    { id="WLK_COMP_01", minL=10, maxL=60, cat="MOB_LEVEL_HIT_CAP", cond="Solo Grinding Same-Level Mobs (4% Base Spell Miss) vs. Raid Bosses (16% Base Spell Miss)", free="Suppression (105924) (Reduce from 5/5 to 2/5 during Solo Leveling!)", shift="Improved Corruption (105925) (5/5 = Instant Cast!) + Improved Life Tap (105921) (2/2 = +20% Mana!)", gain="9.1", why="Against same-level solo mobs, base spell miss is only 4%, so 2/5 Suppression (+4% Affliction Hit) already caps you at 99% Hit! Putting 5/5 in Suppression while soloing wastes 3 talent points that belong in Improved Life Tap (2/2) and Improved Drains!" },
    { id="WLK_COMP_04", minL=10, maxL=60, cat="RACIAL_ADVANTAGE", cond="Race == Undead (Cannibalize 35% HP & 35% Mana) OR Healer Partner with Renew/Rejuvenation", free="Improved Healthstone / Improved Health Funnel (105905)", shift="Improved Life Tap (105921) + Soul Harvesting (105922) + Pandemic (110876)", gain="11.4", why="Life Tap converts HP -> Mana at 120% efficiency, and Undead Cannibalize (or a Healer's HoT) instantly refills your HP bar, giving you infinite mana and 0-second downtime between pulls forever." },
    { id="WLK_COMP_08", minL=10, maxL=24, cat="GEAR_MILESTONE", cond="Equipped High-DPS Wand (Greater Magic Wand L13 / Gravestone Scepter L18) + Corruption + Agony", free="Bane (105888) [Before Level 24 when Shadow Bolt mana is inefficient]", shift="Improved Corruption (105925) + Improved Bane of Agony (105920) + Demonic Embrace (105907)", gain="13.0", why="From Levels 10-24, casting Instant Corruption + Agony + Immolate while your Voidwalker/Imp attacks and wanding to death uses 60% less mana than hard-casting Shadow Bolts." },
    { id="WLK_COMP_02", minL=24, maxL=60, cat="GEAR_MILESTONE", cond="Equipped Shadoweave / 'of Shadow Wrath' Gear (>= +80 Shadow Damage) + Drain Life Drain-Tanking", free="Improved Voidwalker (105904) (Switch from Voidwalker to Succubus/Imp Battery!)", shift="Fel Concentration (105918) (70% Pushback Resist on Drain Life!) + Siphon Life (105912) + Shadow Mastery (105910)", gain="16.8", why="Once you have +Shadow Damage gear and 3/3 Fel Concentration, YOU become the tank via Drain Life + Siphon Life while using Imp (Dark Pact battery) or Succubus for +35% higher kill speed than a Voidwalker!" },
    { id="WLK_COMP_03", minL=30, maxL=60, cat="PARTY_COOP_BUFF", cond="5-Man Dungeon / Raid where Tank Holds Aggro (Sacrifice Succubus for +15% Shadow or Imp for +15% Fire!)", free="Soul Link (105892) [when not taking damage in PvE group]", shift="Demonic Sacrifice (105900) (+15% Shadow/Fire Damage for 30 min!) + Ruin (105883) (Destruction)", gain="14.3", why="When a group tank holds aggro and you don't need pet mitigation, Demonic Sacrifice (+15% Shadow or Fire damage) paired with Ruin (+100% Crit Damage bonus) turns you into a heavy artillery cannon." },
    { id="WLK_COMP_05", minL=35, maxL=60, cat="GEAR_MILESTONE", cond="Spell Crit >= 15% + Pandemic (110876) Unlocked in Affliction Row 4", free="Curse of Exhaustion (105913)", shift="Pandemic (110876) (DoTs Can Critically Strike!) + Ruin (105883) + Shadow Mastery (105910)", gain="18.5", why="Forever's [Pandemic] allows your periodic DoT ticks (Corruption, Bane of Agony, Siphon Life, Wrack) to critically strike, scaling exponentially with Crit and Shadow Mastery." },
    { id="WLK_COMP_06", minL=40, maxL=60, cat="PARTY_COOP_BUFF", cond="2-Target Cleave Pulls with Bane of Havoc (105876) + Incinerate (105874)", free="Pyroclasm (105878)", shift="Bane of Havoc (105876) + Fire and Brimstone (105877) + Conflagrate (105880) + Incinerate (105874)", gain="15.2", why="Placing Bane of Havoc on a second target mirrors 15% of all your single-target Incinerate, Conflagrate, and Shadowburn nukes onto the second mob for free." },
    { id="WLK_COMP_07", minL=40, maxL=60, cat="PARTY_COOP_BUFF", cond="5-Man / Raid Group with Casters & Melee + Demonic Pact (105890) Unlocked", free="Solo drain talents", shift="Demonic Pact (105890) + Demonic Knowledge (105893) + Master Demonologist (105891)", gain="16.0", why="Forever's [Demonic Pact] increases your spell damage by 10% AND buffs the entire party's Spell Power & Attack Power by 10% of your Spell Damage whenever your pet crits!" },
  },
  ["WARRIOR"] = {
    { id="WAR_COMP_01", minL=10, maxL=60, cat="WEAPON_SPEED_SYNC", cond="Equipped Slow 2H Weapon (Speed >= 3.40s, e.g. Whirlwind Axe 11726, Corpsemaker 6687) + Windfury Totem / Blessing of Might", free="Improved Heroic Strike (105958) / Unbridled Wrath (105937)", shift="Two-Handed Weapon Specialization (105948) + Deep Wounds (105950) + Impale (105947)", gain="11.8", why="Heroic Strike replaces next white swing (starving Rage generation), whereas a slow >=3.40s 2H weapon with Windfury Totem generates massive Rage chunks per swing and scales instant weapon-damage strikes (Overpower, Cleave, Sweeping Strikes, Mortal Strike) + Deep Wounds bleed ticks exponentially." },
    { id="WAR_COMP_02", minL=10, maxL=60, cat="RACIAL_ADVANTAGE", cond="Race == Orc (Savage +1% Crit & Blood Fury +10% AP) OR Active Buff: Leader of the Pack (+5% Crit) / Elixir of the Mongoose", free="Improved Rend (105956) [after Deep Wounds unlocked] / Booming Voice (105938)", shift="Flurry (105928) / Impale (105947) / Cruelty (105939)", gain="9.4", why="Once baseline Crit crosses the 18%-20% threshold via Orc Savage, Agility Elixirs, or Feral Leader of the Pack, crit-triggered multipliers (Flurry +25% attack speed, Impale +20% crit bonus damage, Deep Wounds) stay active on virtually every mob pull." },
    { id="WAR_COMP_05", minL=10, maxL=45, cat="CONSUMABLE_ELIXIR", cond="Troll Regeneration + High-Spirit Out-of-Combat Swap Set + Heavy Mageweave Bandages + Well Fed Buff", free="Blood Craze (105953)", shift="Improved Cleave (105934) / Piercing Howl (105935)", gain="5.9", why="External sustain (Bandages, Food/Spirit swap weapon, or Co-Op Renew/Rejuvenation) completely compensates for Blood Craze's 3% health regen, freeing 3 talent points in Row 3 Fury for Improved Cleave and Piercing Howl kiting." },
    { id="WAR_COMP_07", minL=12, maxL=39, cat="CONSUMABLE_ELIXIR", cond="Active Rage Potions + Improved Charge (2/2) + Tactical Mastery (5/5) Stance-Dancing", free="Anger Management (105951) [if in continuous chain-pull combat]", shift="Improved Overpower (105952) (2/2 = +50% Crit on Dodge!)", gain="7.6", why="With Improved Tactical Mastery retaining up to 25 Rage across stances, switching to Battle Stance the instant a mob dodges triggers a ~65% guaranteed crit Overpower." },
    { id="WAR_COMP_04", minL=15, maxL=60, cat="PARTY_COOP_BUFF", cond="Party Healer Active + Paladin Devotion Aura / Shaman Stoneskin Totem + High-Armor Shield + Shield Spike", free="Toughness (105975) / Anticipation (105976)", shift="Defiance (105967) + Improved Revenge (105971) + Cruelty (105939)", gain="10.5", why="When external armor buffs (Devotion Aura/Stoneskin) and blue dungeon shields already mitigate physical damage, excess armor/defense reduces Rage gained from taking hits. Shifting points into Defiance (+15% threat) and Cruelty (+5% crit) prevents DPS from pulling aggro." },
    { id="WAR_COMP_03", minL=20, maxL=60, cat="MOB_LEVEL_HIT_CAP", cond="Solo Grinding Green/Same-Level Mobs (Mob Level <= Player Level) OR Equipped +2% to +4% Hit Gear", free="Precision (105978)", shift="Dual Wield Specialization (105932) + Enrage (105931) + Improved Execute (105926)", gain="6.8", why="Against same-level or -1/-2 level solo mobs, yellow attack miss chance is only 5%. If you already wear +Hit leather/mail or fight green/yellow mobs, shifting points out of Precision into Enrage (+25% damage) and Dual Wield Spec (+25% offhand damage) yields higher raw DPS." },
    { id="WAR_COMP_06", minL=30, maxL=60, cat="GEAR_MILESTONE", cond="Equipped High-Crit / Axe Gear + Sweeping Strikes (105945) Unlocked in Dungeon/Multi-Mob Pulls", free="Improved Hamstring (110858)", shift="Weaponmaster (110524) + Bloodthrill (105944)", gain="8.7", why="In PvE 2-mob cleave pulls, Improved Hamstring immobilization is unnecessary; shifting those points into Forever's Weaponmaster and Bloodthrill maximizes Sweeping Strikes + Whirlwind burst." },
    { id="WAR_COMP_08", minL=40, maxL=60, cat="GEAR_MILESTONE", cond="Equipped Thrash Blade (17705) + Hand of Justice (11815) Extra-Swing Procs", free="Improved Slam (105942)", shift="Unbridled Wrath (105937) + Dual Wield Specialization (105932) + Raging Blows (105977)", gain="9.2", why="Extra-attack proc items (Thrash Blade, Hand of Justice, Windfury) double-dip with Unbridled Wrath Rage procs and Flurry haste, making fast Dual-Wield + Bloodthirst + Raging Blows outscale casted Slam." },
  },
}

