V.RoyalGuildRoster = {
  [1] = { slot=1, code="THE ROYAL BANKER & AH SOVEREIGN (Guild Master Liaison)", cls="Mage (or Warlock/Priest)", ally="Human (Diplomacy +10% Rep / Mercantile Flair)", horde="Undead or Blood Elf/Troll (Capital City Hub Access)", p1="Enchanting", p2="Alchemy", sec="Cooking + First Aid (Campfire & Curative Hub)", syn="Parked 100% at Capital City Mailbox/AH/Bank bridge (Stormwind/Ironforge or Orgrimmar/Thunder Bluff). Mage Teleport at Lv 20+ allows instant inter-city AH arbitrage! Levels in quick rested-XP bursts (Lv 5 -> 10 -> 20 -> 35) to unlock Journeyman, Expert & Artisan Enchanting + Alchemy.", legacy="Account-Wide Legacy Trees: Resourcefulness (Increased Disenchanting yield + Vendor discount) + Professions (Reduced crafting time & bonus skill points).", inb="Receives ALL unwanted BoE Greens (for Disenchanting), ALL Herbs (from Druid/Shaman), ALL Enchanting Rods (from Blacksmith), Elemental Reagents, and Surplus BoE Blue/Purple flips from the 9 field alts.", outb="Produces: (1) Enchanted Tier 1 White Eternal Heirlooms (+100 HP, +9 Stam, +5/+7 Weapon Dmg, Minor Speed), (2) Early Wands (Novice's Practice Wand, Lesser/Greater Magic Wand), (3) Elixirs & Mana Potions for BOTH field alts AND our Leatherworker's Forceful/Mystic Armor Kits, (4) Daily Arcanite/Elemental Transmutes.", ah="Disenchant Shuffle (Buy cheap AH greens -> DE into Strange/Soul/Vision/Dream Dust & Essences), Elixir/Potion stacks, Enchanted BoE Heirlooms, and Transmute cooldowns.", rule="Advance to Lv 5 immediately (unlocks DE + Apprentice Profs to 75), Lv 10 in Band 2 (Skill 150), Lv 20 in Band 4 (Skill 225), and Lv 35 in Band 5 (Skill 300 Artisan)." },
  [2] = { slot=2, code="THE BAG & CLOTH BARON (AoE Cloth & Bag Factory)", cls="Mage (or Priest)", ally="Gnome (+5% Intellect Expansive Mind)", horde="Troll (Berserking Haste) or Undead", p1="Tailoring", p2="Skinning (Early/Mid) or Herbalism", sec="First Aid (Poultices & Tourniquets)", syn="Mage AoE farming shreds humanoid camps for 3x faster Linen, Wool, Silk, Mageweave, and Runecloth drops while Skinning beasts for the Heavy/Thick/Rugged Leather required by Silk/Runecloth Bags! Free Conjured Water means zero gold spent on drinks.", legacy="Legacy Professions Tree (+Cloth scavenging & specialty bag crafting efficiency).", inb="Receives Heavy/Thick/Rugged Leather from Skinning/LW alts, Vision Dust/Essences from Banker Enchanter (for Enchanted Bags), and Dyes/Thread.", outb="Produces: ALL Standard Bags (6 to 16 slot) + ALL WoW Forever Custom Reagent Bags (Linen, Woolen, Silk, Mageweave, Runecloth, Mooncloth, Bottomless) for every alt in the guild + Banker's 6 bank slots, plus Spellpower Cloth BoEs.", ah="Monopolizes the AH Bag & Custom Reagent Bag market! Every player on WoW Forever needs Reagent Bags and Standard Bags.", rule="Levels in lockstep with the roster; clears humanoid camps in each bracket to guarantee 4x Standard Bags + 1x Reagent Bag for every alt." },
  [3] = { slot=3, code="THE ARMOR KIT & QUIVER ARTISAN (Hide & Beast Master)", cls="Hunter", ally="Night Elf (Shadowmeld + +2% Dodge + Bow Spec)", horde="Orc (Command +5% Pet Damage) or Tauren", p1="Skinning", p2="Leatherworking", sec="Cooking (Pet Food + Group Stamina/Spirit Buffs)", syn="Hunter is the #1 beast-slaying machine in 1.60.1 (zero downtime, Aspect of the Cheetah at Lv 20). Skins every beast instantly and crafts its own Quivers (Light/Heavy/Quickdraw) for +10-15% ranged attack speed AND all 15 Leatherworking Armor Kits!", legacy="Legacy Adventure (+Movement Speed) + Legacy Professions (+Skinning yield & Leatherworking recipes).", inb="Receives Strange/Soul/Vision/Dream Dust AND Elixir of Minor Strength / Giant Growth / Ogre Strength + Mana Potions from the Banker Liaison to upgrade basic Armor Kits into Forever-exclusive FORCEFUL and MYSTIC Armor Kits!", outb="Produces: (1) All 15 Armor Kits (Light, Medium, Forceful/Mystic Medium, Heavy, Forceful/Mystic Heavy, Thick, Forceful/Mystic Thick, Rugged, Forceful/Mystic Rugged, Wild, Core) applied to Chest, Hands, Legs & Feet, (2) Quivers & Ammo Pouches, (3) Light Leather Reagent Bags & Camp Tents, (4) Heavy/Thick/Rugged Leather for Tailor & Blacksmith.", ah="Sells Forceful & Mystic Armor Kits, Quickdraw Quivers, Wicked Leather, and Devilsaur/Cured Hides for massive AH profit.", rule="Leads beast-grinding circuits in every level band so the entire guild stays equipped with 4/4 Forceful or Mystic Armor Kits on their White Heirlooms." },
  [4] = { slot=4, code="THE BOTANICAL SPEEDSTER (Stealth/Travel Form Gatherer)", cls="Druid", ally="Night Elf (Shadowmeld Stealth Gathering)", horde="Tauren (+15 Herbalism Cultivation + War Stomp)", p1="Herbalism", p2="Mining (or Skinning)", sec="Fishing + Cooking", syn="Druid can gather Herbs in Travel Form (+40% speed at Lv 30) and Aquatic Form, stealth past elites with Prowl to snag node spawns in caves, and never dismounts for form shifts! Tauren Druids get +15 Herbalism so they can pick Silverleaf/Peacebloom/Mageroyal/Briarthorn zones early.", legacy="Legacy Resourcefulness (+Gathering node radar & double-gather proc chance).", inb="Receives Bags, Forceful/Mystic Armor Kits, and Enchanted Heirlooms from the Banker & Tailor/LW.", outb="Produces: 100% of the guild's Herbs (Peacebloom, Silverleaf, Briarthorn, Mageroyal, Bruiseweed, Liferoot, Kingsblood, Fadeleaf, Sungrass, Gromsblood, Golden Sansam, Black Lotus) + Ores/Stones mailed every 30 mins to the Banker Alchemist & Blacksmith!", ah="Supplies the Banker Alchemist for zero-cost Elixirs/Potions/Transmutes and sells excess high-demand herbs & Elemental Earth/Water on the AH.", rule="Cruises through open-world circuits between quest hubs, filling Reagent Bags with herbs and ores." },
  [5] = { slot=5, code="THE FORGE & ENCHANTING ROD TITAN (Plate, Weapons & Rods)", cls="Paladin (or Warrior)", ally="Dwarf (Find Treasure + Stoneform + Mace/Gun Spec) or Human (+5 Mace/Sword)", horde="Orc (Axe Spec + Hardiness) or Tauren", p1="Mining", p2="Blacksmithing", sec="First Aid", syn="Paladin gets a FREE Level 40 Mount (saving 90g for the guild empire!) + Crusader Aura / Pursuit of Justice (+movement speed for mining loops) + AoE Protection farming. Crafts all Inert Enchanting Rods (Copper, Silver, Golden, Truesilver, Arcanite) required by the Banker Enchanter!", legacy="Legacy Professions (+Smelting & Blacksmithing skill) + Legacy Resourcefulness.", inb="Receives Ores/Stones from Druid/Hunter gatherers, Leather from Hunter, and Enchanted Heirlooms from Banker.", outb="Produces: (1) Inert Copper/Silver/Golden/Truesilver/Arcanite Rods for the Banker Enchanter + AH sale, (2) Sharpening Stones & Weightstones (Rough through Elemental) for all melee alts, (3) Shield Spikes & Belt Buckles, (4) Portable Anvils & Sharpening Wheels, (5) Heavy Mail/Plate BoEs & Silvered Bronze/Mithril gear.", ah="Monopolizes the Inert Enchanting Rod, Shield Spike, Belt Buckle, and Weapon Stone markets on the AH.", rule="Mines every vein along quest routes; hits Skill 15/100/150/200/275 right on time to mail Enchanting Rods to the Banker." },
  [6] = { slot=6, code="THE GADGET, SCOPE & BOT ENGINEER (Field Utility & Salvage)", cls="Rogue (or Hunter/Warrior)", ally="Gnome (+15 Engineering Technologist!) or Dwarf", horde="Orc or Undead (Stealth Lockbox & Rich Thorium Cave Mining)", p1="Mining", p2="Engineering", sec="Lockpicking + First Aid", syn="Gnome gets +15 Engineering (unlocking Goggles, Scopes, and Bots 15 skill points early!), while Rogue Stealth + Pick Lock opens all locked chests, doors, and Lockboxes mailed from the other 8 alts! Crafts Portable Reagent Bots (gray=25) and Repair Bots (gray=145) for the guild!", legacy="Legacy Resourcefulness + Legacy Professions.", inb="Receives Locked Chests/Lockboxes from all guild alts, Cloth from Tailor, Leather from LW, and Ores/Gems from Mining alts.", outb="Produces: (1) Scopes (Crude, Standard, Accurate, Deadly, Sniper) for White Heirloom Bows/Guns, (2) Portable Reagent Bots & Repair Bots for field deployment, (3) Early Head-slot Goggles (Flying Tiger Goggles at Lv 10!), (4) Target Dummies, Grenades & Sapper Charges, (5) Unlocked Lockbox loot.", ah="Sells Scopes, Repair Bots, Deadly Blunderbusses (Ashenvale Quest Item!), Mithril Casings, and Hi-Explosive consumables on AH.", rule="Levels alongside roster; unlocks all guild Lockboxes at the mailbox and keeps Hunters/Warriors/Rogues scoped." },
  [7] = { slot=7, code="THE TOTEMIC ELEMENTAL HARVESTER (Cross-Faction / Hybrid Powerhouse)", cls="Shaman", ally="Dwarf/Draenei (or Cross-Faction Forever Queue)", horde="Troll (Berserking) or Orc/Tauren", p1="Herbalism", p2="Skinning (or Alchemy Transmute Alt at Lv 35)", sec="Fishing (Oily Blackmouth, Firefin, Stonescale Eel)", syn="Ghost Wolf at Lv 20 (+40% outdoor movement speed) + Water Walking at Lv 28 makes Shaman the ultimate coastal/river Herb, Skinning & Fishing harvester (Oily Blackmouth -> Free Action Potions; Stonescale Eel -> Stonescale Oil). At Lv 35, can swap Skinning for 2nd Alchemy to double daily Arcanite/Elemental Transmutes!", legacy="Legacy Adventure + Legacy Resourcefulness.", inb="Receives Enchanted Heirlooms, Forceful/Mystic Armor Kits, and 4x Bags + 1x Reagent Bag.", outb="Produces: Coastal Herbs (Stranglekelp), Alchemical Fish (Oily Blackmouth, Firefin Snapper, Stonescale Eel), Thick/Rugged Leather, and 2nd Daily Transmute Cooldown at Lv 35.", ah="High-margin Alchemical Fish oils & 2nd Daily Transmute cooldown printer.", rule="Sweeps coastal zones (Barrens/Westfall/STV/Tanaris/Feralas) where Ghost Wolf + Water Walking cut travel time in half." },
  [8] = { slot=8, code="THE SHADOW SOUL & SUMMONING ANCHOR (Zero-Downtime Grinder)", cls="Warlock", ally="Gnome (+5% Int) or Human", horde="Orc (+5% Pet Damage) or Undead (Will of the Forsaken)", p1="Tailoring (Mooncloth/Felcloth CD)", p2="Herbalism (or Mining)", sec="First Aid (Heavy Bandages for Life Tap)", syn="Free Level 40 Felsteed (saves another 90g!) + Voidwalker tank + Drain/Wand autopilot = nonstop grinding of humanoid/demon camps for Cloth, Felcloth, and Herbs. Ritual of Summoning at Lv 20 lets our guild teleport the Banker Liaison or other alts to neutral AH / key hubs!", legacy="Legacy Professions (Mooncloth CD efficiency) + Legacy Adventure.", inb="Receives Early Enchanted Wands + Mystic Armor Kits + Bags from Banker & Tailor.", outb="Produces: 2nd Mooncloth Cooldown at Skill 250, Felcloth & Demonic Runes from Satyr camps, Soul Pouches, plus Summoning logistics.", ah="Passive Mooncloth cooldown gold + Felcloth Bag reagents.", rule="Farms humanoid/demon camps with zero drinking downtime using First Aid + Life Tap." },
  [9] = { slot=9, code="THE HOLY WAND & DUNGEON CARRIES TITAN (Spirit Tap Machine)", cls="Priest", ally="Dwarf (Fear Ward) or Human (+10% Spirit)", horde="Troll (Shadowguard/Hex) or Undead (Devouring Plague)", p1="Tailoring (3rd Mooncloth CD)", p2="Skinning (or Enchanting Disenchant Field Alt)", sec="Cooking + First Aid", syn="With our Banker's Lv 5 Enchanted Wand + Spirit Tap + Mystic Armor Kits, Priest has 0% downtime solo and instant dungeon healer queues to funnel dungeon BoEs and cloth to the Banker.", legacy="Legacy Resourcefulness + Legacy Professions.", inb="Receives Novice's Practice Wand (Lv 5), Lesser Magic Wand (Lv 5), Greater Magic Wand (Lv 13), and Mystic Armor Kits.", outb="Produces: High-volume Dungeon Cloth, BoE Dungeon Blues/Greens for the Banker's Disenchanting & AH engine, and a 3rd Mooncloth Cooldown at Skill 250.", ah="Dungeon BoE farm + 3rd Mooncloth Cooldown.", rule="Glides through bands 1-60 with zero mana breaks via Wand Spec + Spirit Tap." },
  [10] = { slot=10, code="THE JUGGERNAUT CLEAVE VANGUARD (Heirloom-Fed Hyper-Carry)", cls="Warrior", ally="Human (+5 Sword/Mace Spec) or Gnome (Escape Artist)", horde="Orc (+5 Axe Spec + Blood Fury) or Troll (Berserking)", p1="Mining", p2="Herbalism (or Engineering)", sec="First Aid (Tourniquets, Poultices & Bandages)", syn="Normally the most gear-dependent class in WoW—but when fed our Banker's Enchanted White Heirlooms (+100 HP Chest, Fiery/Striking Weapon, +9 Stam Shield, Minor Speed Boots) + 4x Forceful Armor Kits + Blacksmith Sharpening Stones + Alchemy Strength/Troll's Blood Elixirs, Warrior becomes an unstoppable cleave god from Level 1!", legacy="Legacy Adventure + Legacy Resourcefulness.", inb="Receives the full Royal Tier 1 Eternal White Heirloom Plate/Mail/Leather package, Forceful Armor Kits, Sharpening Stones, and Elixirs.", outb="Produces: Dual-Gathering Ores + Herbs while cleaving 2-3 mobs at a time, plus instant Tank dungeon queues.", ah="Feeds raw Ores, Dense Stone, and Herbs to the Banker and Blacksmith.", rule="Never hits a gear wall because every 5 levels a newly enchanted/kitted weapon and armor package waits in the mailbox." },
}

V.SynchronizedWorkflowBands = {
  [1] = { band="Band 1: Levels 1 -> 5 (Starter Zone Ignition & Banker Unlock)", bankerLvl=5, cap=75, bags="3x Linen Bag (6-slot each, Tailoring gray=65)", regBag="1x Linen Reagent Bag (Tailoring gray=65) OR 1x Light Leather Reagent Bag (LW gray=50)", slots="16 Backpack + 18 Standard + 6-8 Reagent = 40-42 Slots at Level 5!", kits="4x Light Armor Kit (+8 Armor each = +32 Armor across Chest, Hands, Legs, Feet) applied to Tier 1 White Heirlooms!", ench="Banker Enchanter crafts Novice's Practice Wand (gray=40, 1x Simple Wood + 2x Strange Dust) & Lesser Magic Wand (Lv 5) + Minor Health (+15 HP) / Minor Absorption (+10-25 HP) on White Chests + Rough Sharpening/Weightstones (+2 Weapon Dmg)!", alch="Minor Healing Potions + Elixir of Lion's Strength (+4 Str) + Elixir of Minor Fortitude (+27 HP) + Basic Campfire (+4 Spirit) + Portable Camp Tent / Enchanted Lute / Reagent Bot (gray=25)!", inMail="Every alt mails ALL Linen Cloth, Light Leather, Copper Ore, Rough Stone, Peacebloom, Silverleaf, and Lv 5+ Green drops to the Banker Liaison before leaving the starter sub-zone.", outPack="Banker & Crafters mail back: (1) 3x Linen Bags + 1x Linen/Leather Reagent Bag, (2) 4x Light Armor Kits, (3) Enchanted Tier 1 White Heirloom set (never binds!), (4) Novice/Lesser Magic Wand for Casters or +Weapon Dmg / Sharpening Stones for Melee.", ahFlip="Sell surplus Linen Reagent Bags, Light Leather Reagent Bags, Inert Copper Rods, and Lesser Magic Wands on the AH to fund Guild Charter (10s), Guild Tabard, and all Lv 4-6 Trainer spells." },
  [2] = { band="Band 2: Levels 5 -> 10 (Journeyman Unlock & Forceful/Mystic Kit Spike)", bankerLvl=10, cap=150, bags="3x Woolen Bag (8-slot, gray=110) or Kodo Hide Bag", regBag="1x Woolen Reagent Bag (Tailoring gray=110)", slots="16 Backpack + 24 Standard + 8-10 Reagent = 48-50 Slots at Level 10!", kits="4x FORCEFUL Medium Armor Kit (1x Medium Kit + 2x Strange Dust + 2x Elixir of Minor Strength) for Melee OR 4x MYSTIC Medium Armor Kit (1x Medium Kit + 2x Strange Dust + 2x Minor Mana Potion) for Casters!", ench="Banker hits Lv 10 (Journeyman Enchanting/Alchemy 150): Minor Speed to White Boots (+8% Run Speed!), +5/+7 Stamina to White Shield/Bracers, +3/+5 Striking to White 1H/2H Weapons, Crude Scope (+1 Ranged Dmg) on White Bow/Gun, Light Leather Quiver (+10% Ranged Speed)!", alch="Elixir of Wisdom (+6 Int), Elixir of Giant Growth (+8 Str & Size!), Swiftness Potion, Weak/Strong Troll's Blood Potion, First Aid Anti-Venom & Simple Poultice!", inMail="Alts mail Wool Cloth, Medium Leather, Tin/Silver/Bronze Ore, Coarse Stone, Mageroyal, Briarthorn, Stranglekelp, Small Venom Sacs, and all Lv 6-12 BoE Greens.", outPack="Banker disenchants greens into Strange/Soul Dust & Greater Magic/Lesser Astral Essences; brews Elixir of Minor Strength & Minor Mana Potions; sends them to Leatherworker to craft 4x Forceful/Mystic Medium Armor Kits for every alt!", ahFlip="Monopoly flip: Forceful & Mystic Medium Armor Kits (huge AH margins because solo players lack the Enchanter + Alchemist + LW trifecta!), Inert Silver Rods, Flying Tiger Goggles, and Woolen Reagent Bags." },
  [3] = { band="Band 3: Levels 10 -> 20 (Expert Unlock, Greater Magic Wand & Portable Stations)", bankerLvl=20, cap=225, bags="3x Small Silk Pack (10-slot, gray=175) or Green/Black Silk Pack", regBag="1x Silk Reagent Bag (Tailoring gray=140)", slots="16 Backpack + 30 Standard + 10-12 Reagent = 56-58 Slots at Level 20!", kits="4x FORCEFUL Heavy Armor Kit (1x Heavy Kit + 2x Soul Dust + 2x Elixir of Giant Growth) OR 4x MYSTIC Heavy Armor Kit (1x Heavy Kit + 2x Soul Dust + 2x Lesser Mana Potion)!", ench="Greater Magic Wand (Lv 13, 17.5 DPS!) -> Mystic Wand, Heavy Sharpening/Weightstones (+4 Dmg), Standard Scope (+2 Dmg), Heavy Quiver / Ammo Pouch (+11% Speed), Iron Shield Spike, Enchant Bracer +7/+9 Stamina, Chest +50/+100 HP!", alch="Portable Arcane Salvager (Enchanting gray=145), Portable Repair Bot (Engineering gray=145), Portable Mana Well (Alchemy gray=145), Tanning Rack & Spinning Wheel! Plus Free Action Potions, Elixir of Defense, Elixir of Lesser Agility, and Woolen Tourniquets (Bleed removal)!", inMail="Alts mail Silk Cloth, Heavy Leather, Iron/Gold Ore, Heavy Stone, Bruiseweed, Kingsblood, Liferoot, Oily Blackmouth, Locked Chests (to Rogue Engineer), and Dungeon BoEs.", outPack="Banker hits Lv 20 (Expert 225): Crafts Mystic Wands, Soul Dust enchants, and Elixir of Giant Growth / Lesser Mana Potions to fuel Forceful/Mystic Heavy Armor Kits + Portable Repair Bots & Mana Wells.", ahFlip="Flip Deadly Blunderbusses,Bronze Tubes, Iron Buckles, Inert Golden Rods, Silk Reagent Bags, Forceful/Mystic Heavy Armor Kits, and Free Action Potions." },
  [4] = { band="Band 4: Levels 20 -> 30 (Mid-Game Powerhouse & Thick Kit / Mount Prep)", bankerLvl=25, cap=250, bags="3x Mageweave Bag (12-slot, gray=235)", regBag="1x Mageweave Reagent Bag (Tailoring gray=215) or Enchanted Mageweave Pouch", slots="16 Backpack + 36 Standard + 12-14 Reagent = 64-66 Slots at Level 30!", kits="4x FORCEFUL Thick Armor Kit (1x Thick Kit + 2x Vision Dust + 2x Elixir of Ogre Strength) OR 4x MYSTIC Thick Armor Kit (1x Thick Kit + 2x Vision Dust + 2x Mana Potion)!", ench="Solid Sharpening/Weightstones (+6 Dmg), Accurate Scope (+3 Dmg), Quickdraw Quiver / Thick Ammo Pouch (+13% Ranged Speed), Mithril Shield Spike, Fiery Weapon / Demonslaying / +7 Weapon Damage on White Heirlooms!", alch="Elixir of Ogre's Strength (+8 Str), Elixir of Agility (+15 Agi), Elixir of Greater Defense, Frost Oil, Shadow Oil, First Aid Clever Poultice & Leather Tourniquet!", inMail="Alts mail Mageweave Cloth, Thick Leather, Mithril/Truesilver Ore, Solid Stone, Fadeleaf, Khadgar's Whisker, Wild Steelbloom, Firefin Snapper, and Vision Dust greens.", outPack="Banker + Tailor + LW + BS deliver the Level 30 Power Package: 3x Mageweave Bags + 1x Mageweave Reagent Bag + 4x Forceful/Mystic Thick Armor Kits + Quickdraw Quiver + Solid Stones.", ahFlip="Generate 300g+ in Band 4 via Mageweave Reagent Bags, Forceful/Mystic Thick Armor Kits, Quickdraw Quivers, Inert Truesilver Rods, and Transmute: Iron to Gold / Mithril to Truesilver so EVERY alt buys their Level 40 Mount the second they ding!" },
  [5] = { band="Band 5: Levels 30 -> 40 (Artisan 300 Unlock, Level 40 Mounts & Capstone Respec)", bankerLvl=35, cap=300, bags="3x Runecloth Bag (14-slot, gray=260)", regBag="1x Runecloth Reagent Bag (Tailoring gray=260)", slots="16 Backpack + 42 Standard + 14-16 Reagent = 72-74 Slots at Level 40!", kits="4x FORCEFUL Rugged Armor Kit (1x Rugged Kit + 2x Dream Dust + 2x Elixir of Greater Strength + Pristine Scale + Fel Hide) OR 4x MYSTIC Rugged Armor Kit!", ench="Banker hits Lv 35 (Artisan 300 Enchanting & Alchemy Unlocked!): Crafts ALL endgame enchants (+9 Stats, Crusader, +15/25 Agility, Spellpower) + Daily Arcanite/Elemental Transmutes! Plus Deadly Scope (+5 Dmg) & Truesilver Belt Buckles.", alch="Daily Transmute Cooldowns (Banker + Shaman Alt) + Mooncloth Cooldowns (Mage + Warlock + Priest Tailors = 3x Mooncloth CDs!) + Elixir of Giants, Greater Arcane Elixir, Mageblood Potion!", inMail="Alts mail Runecloth, Rugged Leather, Thorium/Truesilver, Dense Stone, Sungrass, Gromsblood, Purple Lotus, Stonescale Eel, and Dream Dust greens.", outPack="Banker funds 1g Level 40 Capstone Respecs (Phase 2) + 90g Level 40 Mounts for non-Paladin/Warlock alts, and sends Runecloth Bags + Runecloth Reagent Bags + Artisan Enchants.", ahFlip="Daily Passive Cooldown Empire online at Level 35: 2x Alchemy Transmutes + 3x Tailoring Mooncloth Cooldowns + Cured Rugged Hide CDs printing passive gold every 24-96 hours." },
  [6] = { band="Band 6: Levels 40 -> 50 (Pre-BiS Crafting, Thorium & Mooncloth Expansion)", bankerLvl=35, cap=300, bags="3x Mooncloth Bag (16-slot, gray=300) or Enchanted Runecloth Bag", regBag="1x Mooncloth Reagent Bag (Tailoring gray=300) or Cenarion Herb Bag", slots="16 Backpack + 48 Standard + 16-20 Reagent = 80-84 Slots at Level 50!", kits="4x Forceful/Mystic Rugged Armor Kits or Wild Leather Armor Kits (gray=325)!", ench="Dense Sharpening/Weightstones (+8 Dmg), Sniper Scope (+7 Dmg), Thorium Shield Spike, Thorium Belt Buckle, Crusader / Lifestealing / Icy Chill / +9 Bracer / +7 Boots.", alch="Portable Arcane Forge (gray=300), Anarchist's Workbench (gray=300), Alchemy Lab (gray=300), Iron Oven (gray=300), Loom & Sewing Machine (gray=300), plus Surgical Tourniquets & Powerful Poultices!", inMail="Alts mail Rich Thorium, Arcane Crystals, Felcloth, Enchanted Leather, Essences, Golden Sansam, Mountain Silversage, and Plaguebloom.", outPack="Full Pre-BiS Crafted Sets (Devilsaur Set, Bloodvine/Mooncloth, Imperial Plate, Thorium Gadgets) + Portable Artisan Stations.", ahFlip="Arcanite Bar transmutes, Mooncloth Bags, Mooncloth Reagent Bags, Devilsaur Sets, and Enchanting Vellum/Service fees." },
  [7] = { band="Band 7: Levels 50 -> 60 (Sovereign Endgame & Bottomless Vault Mastery)", bankerLvl=35, cap=345, bags="3x Core Felcloth / Big Bag of Enchantment / Satchel of Cenarius / Mooncloth Bag", regBag="1x Bottomless Reagent Bag (Tailoring gray=345)", slots="16 Backpack + 54 Standard + 24-28 Reagent = 94-98 Total Carry Slots!", kits="4x Core Armor Kit (gray=340) + Forceful/Mystic Rugged Kits!", ench="Elemental Sharpening Stones (+2% Crit!), SAF-T Ultra Precision Scope / Biznicks 247x128 Accurascope (+3% Hit!), Inert Arcanite Rod, +30 Spell Power / +55 Healing / Crusader.", alch="Flasks, Draught of the Titans / Ancients, Major Mana & Healing Potions, Mageblood, Elixir of the Mongoose, Elemental Fire/Earth/Water.", inMail="Endgame Raid/Dungeon/World materials funnel directly into the Royal Guild Bank.", outPack="Every Level 60 alt steps immediately into raids/PvP with full Epic/Pre-BiS crafted gear, 90+ bag slots, and unlimited consumables.", ahFlip="Complete Server AH Dominance across Bags, Armor Kits, Consumables, Enchanting Rods, and BoE Heirlooms." },
}

V.IgnitionSequence = {
  [1] = { step=1, label="IGNITION STEP 1: The Backbone Skinner Pioneer (Starter Sub-Zone -> Lv 6-7)", slot="Slot 3: THE ARMOR KIT & QUIVER ARTISAN", profs="Hunter (Skinning at Lv 2-3 + Leatherworking at Lv 5)", fromL=1, toL=7, mins=45, unlock="At Lv 1 you have 0 copper. Quest 1->3 in starter valley (12 mins) to loot ~1.5 Silver. Walk to first town (Goldshire/Razor Hill/Kharanos/Dolanaar) at Lv 3, buy Skinning Knife (82c) + train Skinning (10c, NO level 5 requirement!). Grind beasts + starter quests to Lv 6-7 (Skinning hits ~45-60). Run to Capital City at Lv 5-6 to train Apprentice Leatherworking (10c) & Cooking.", g70="Keep 70% of Light Leather (~35x), Ruined Leather Scraps, Linen Cloth (~20x), and craft 4x Light Armor Kits (+8 Armor) + 3-4x Embossed Leather Vests / Handstitched Leather Belts (BoE LW Greens!). Mail these + 8 Silver seed coin to Slot 1 (The Royal Banker).", ah30="Post 30% of haul on the Capital City AH: 1-2 stacks of Light Leather + 2x Light Armor Kits. Generates your first 15-30 Silver in steady liquid cash while you log onto the next toon!", math="Starting with the Hunter Skinner to Lv 6-7 solves the 'Zero-Copper & Level-5 Gate Paradox': Skinning unlocks before Lv 5, beasts drop the highest vendor gray value per kill, and by Lv 7 your Hunter funds the Banker's training AND crafts the exact Lv 5 Leatherworking BoE Greens the Banker needs to Disenchant!" },
  [2] = { step=2, label="IGNITION STEP 2: The Royal Banker & AH Sovereign (Lv 1 -> Lv 5 Capital City Lock-In)", slot="Slot 1: THE ROYAL BANKER & AH SOVEREIGN", profs="Mage (Enchanting + Alchemy at Lv 5)", fromL=1, toL=5, mins=22, unlock="Power-level 1->5 in starter valley (22 mins), then immediately run to the Capital City (Stormwind/Ironforge or Orgrimmar/Thunder Bluff). Open the Hunter's mail (8 Silver + LW Greens + Linen + Light Armor Kits). Train Apprentice Enchanting (10c) + Apprentice Alchemy (10c) right at Level 5!", g70="Disenchant the Hunter's crafted LW Greens at Enchanting Skill 1 -> yields Strange Dust + Lesser Magic Essence! Craft Runed Copper Rod (once Blacksmith sends Inert Copper Rod in Step 3) + Novice's Practice Wand / Lesser Magic Wand (Lv 5, 11.3 DPS!). Park Banker at Capital City AH/Bank/Mailbox.", ah30="List 30% of surplus Strange Dust or 1x Lesser Magic Wand on AH (sells for 8-15 Silver to caster mains!). Register Guild Charter at Guild Master.", math="Getting the Banker to Level 5 second unlocks Apprentice Enchanting (Skill 1-75) + Disenchanting + Apprentice Alchemy (Skill 1-75) BEFORE the rest of the alt army generates hundreds of items, turning the Banker into an active factory instead of a passive mule." },
  [3] = { step=3, label="IGNITION STEP 3: The Forge & Rod Titan (Lv 1 -> Lv 6 Mining + Blacksmithing)", slot="Slot 5: THE FORGE & ROD TITAN", profs="Paladin or Warrior (Mining at Lv 2-3 + Blacksmithing at Lv 5)", fromL=1, toL=6, mins=40, unlock="Open Banker Care Package (Light Armor Kits + 2 Silver). Buy Mining Pick (81c) + learn Mining at Lv 2-3. Mine Copper Veins along starter ridge to Lv 6 (Mining hits ~35). Run to Capital City at Lv 5-6, learn Blacksmithing, smelt Copper Bars, craft Rough Sharpening Stones (hits BS Skill 15), and craft INERT COPPER RODS (1x Rough Grinding Stone + 5x Copper Bar)!", g70="Keep 70% of Copper Bars/Rough Stones; mail 1x Inert Copper Rod + Copper Bars + BoE Greens to the Banker Enchanter, and mail Rough Sharpening Stones (+2 Weapon Dmg) to melee alts.", ah30="List 30% on AH: 2-3x Inert Copper Rods (massive markup because every Enchanter on WoW Forever needs one from a Blacksmith!) + 1 stack of Copper Bars.", math="Unlocks the Banker's Runed Copper Rod at BS Skill 15 so the Banker can immediately enchant Tier 1 White Heirlooms and craft Lesser Magic Wands!" },
  [4] = { step=4, label="IGNITION STEP 4: The Bag & Cloth Baron (Lv 1 -> Lv 7 Tailoring + Skinning)", slot="Slot 2: THE BAG & CLOTH BARON", profs="Mage (Tailoring at Lv 5 + Skinning at Lv 2)", fromL=1, toL=7, mins=40, unlock="Equip the Banker's newly crafted Level 5 Lesser Magic Wand (11.3 DPS — 2-shots every starter mob!). Shred humanoid camps from Lv 1->7 for Linen Cloth. Run to Capital City at Lv 5-6, learn Tailoring, spin Bolts of Linen Cloth, and craft Linen Bags (6-slot) + WoW Forever Custom LINEN REAGENT BAGS (gray=65)!", g70="70% Guild Allocation: Mail 3x Linen Bags + 1x Linen Reagent Bag to the Banker, Hunter, Paladin, and next alts, plus mail White Linen Robes/Brown Linen Vests (BoE Greens) to the Banker to Disenchant!", ah30="30% AH Liquidation: List Linen Bags and Custom Linen Reagent Bags on the AH for instant gold flow.", math="Eliminates the 16-slot backpack bottleneck across the entire account on Day 1. Every alt after Step 4 starts with 3x Linen Bags + 1x Linen Reagent Bag (40-42 total slots!)." },
  [5] = { step=5, label="IGNITION STEP 5: The Botanical Speedster (Lv 1 -> Lv 7 Herbalism + Mining)", slot="Slot 4: THE BOTANICAL SPEEDSTER", profs="Druid (Herbalism + Mining at Lv 2-3)", fromL=1, toL=7, mins=38, unlock="Opens 4-Bag Care Package from Tailor + Light Armor Kits from Hunter. Learns Herbalism + Mining at Lv 2-3 (Tauren starts at 16 Herbalism!). Sweeps starter & border zones for Peacebloom, Silverleaf, Earthroot, Mageroyal, and Copper Ore to Lv 7.", g70="70% Guild Allocation: Mail 50+ Peacebloom/Silverleaf/Earthroot to the Level 5 Banker Alchemist to brew Elixir of Lion's Strength, Elixir of Minor Fortitude, Minor Healing Potions, and Minor Mana Potions!", ah30="30% AH Liquidation: Sell 30% of raw herbs + surplus Minor Healing/Mana Potions on AH.", math="Fuels the Banker Alchemist to hit Alchemy Skill 60+, unlocking Elixir of Minor Strength & Minor Mana Potions—which the Hunter LW needs to craft Forceful & Mystic Medium Armor Kits in Band 2!" },
  [6] = { step=6, label="IGNITION STEP 6: Complete Band 1 Sweep Across Remaining Alts (Lv 1 -> Lv 6-7)", slot="Slots 6, 7, 8, 9, 10 (Rogue, Shaman, Warlock, Priest, Warrior)", profs="Remaining Roster (Engineering, Dual-Gatherers, Tailors)", fromL=1, toL=7, mins=120, unlock="Every remaining alt logs in to a mailbox overflowing with: 3x Linen Bags + 1x Linen Reagent Bag (40 slots!), 4x Light Armor Kits, Enchanted Tier 1 White Heirlooms (+15 HP Chest, +Weapon Dmg / Lesser Magic Wand), and Strength/Fortitude Elixirs! Each alt breezes from Lv 1->7 in ~25 mins and visits the Capital City at Lv 5 to start accumulating Rested XP.", g70="70% of all Linen, Light Leather, Copper Ore, Rough Stone, Herbs, and Locked Chests flow into the Banker & Rogue Engineer.", ah30="30% of all gathered commodities & Portable Reagent Bots (Engineering gray=25) hit the AH.", math="Parking all alts at a Capital City Inn at Level 6-7 activates the 150% Rested XP multiplier across your entire 10-character army!" },
  [7] = { step=7, label="BAND 2 LOCKSTEP RELAY: Banker Lv 5 -> Lv 10 + Roster Lv 7 -> Lv 14", slot="Banker to Lv 10 FIRST, then Roster in Rested XP Rotation", profs="All 10 Characters (Journeyman Profession Cap 150 Unlock)", fromL=7, toL=14, mins=180, unlock="Wait until Banker has Rested XP -> push Banker from Lv 5 -> Lv 10 (takes ~35 mins with Enchanted Wand + Heirlooms) so Banker unlocks JOURNEYMAN ENCHANTING & ALCHEMY (Skill 75->150)! Now the Banker can Disenchant ALL Lv 10-25 Greens (Skill 25-75) and brew Elixir of Giant Growth & Lesser Mana Potions!", g70="70% Guild Allocation: Hunter crafts 4x Forceful Medium Armor Kits & 4x Mystic Medium Armor Kits (using Banker's Strange Dust + Elixirs/Potions); Tailor crafts 8-slot Woolen Bags + Woolen Reagent Bags; Banker crafts Greater Magic Wands (Lv 13, 17.5 DPS!).", ah30="30% AH Liquidation: Post Forceful/Mystic Medium Armor Kits, Woolen Reagent Bags, Greater Magic Wands, and Inert Silver Rods.", math="Pushing the Banker to Lv 10 right as the roster enters Band 2 prevents the Disenchanting & Profession Cap bottleneck (`Skill 75 limit`) so no crafted Leatherworking or Tailoring green ever sits un-disenchanted!" },
  [8] = { step=8, label="BAND 3 & 4 LOCKSTEP RELAY: Banker to Lv 20 (Expert 225) -> Lv 35 (Artisan 300)", slot="Banker to Lv 20 at Roster Lv 18; Banker to Lv 35 at Roster Lv 32", profs="Full Royal Empire (Expert 225 -> Artisan 300 Cap)", fromL=14, toL=60, mins=0, unlock="Keep the Golden Rule of Banker Progression: Unlock Lv 10 Banker when Roster hits Lv 8; Unlock Lv 20 Banker (plus Mage Teleport!) when Roster hits Lv 18; Unlock Lv 35 Banker (Artisan 300 Max Cap!) when Roster hits Lv 32.", g70="70% funds Silk/Mageweave/Runecloth Reagent Bags, Forceful/Mystic Heavy/Thick/Rugged Armor Kits, Portable Repair Bots & Arcane Salvagers, and Level 40 Mounts.", ah30="30% of all Transmutes, Mooncloth CDs, Bags, Armor Kits, and Elixirs sold on AH.", math="In WoW Classic/Forever, Level 35 is the FINAL character level requirement for 300 Artisan professions. Once your Banker hits Level 35, it never needs another XP point to craft 100% of endgame Level 60 Enchants, Flasks, and Transmutes!" },
}

