V.AH7030Ledger = {
  { band="Band 1 (Lv 1-10)", prof="Skinning / LW", item="Light Leather & Ruined Scraps", g70="70% retained by Hunter LW to craft Light Armor Kits (4 per alt) + Embossed Leather Vests for Banker DE.", ah30="Sell 30% as Light Armor Kits (singles) + Light Leather (stacks of 10-20) OR Light Leather Reagent Bags!", stack="Stacks of 10 / Singles for Kits & Bags", margin=240, why="Tailors, Blacksmiths, and Engineers all need Light Leather starting at Skill 25, and every fresh alt buys Light Armor Kits." },
  { band="Band 1 (Lv 1-10)", prof="Tailoring", item="Linen Cloth & Bolts of Linen", g70="70% used by Mage Tailor to equip all 10 guild alts with 3x Linen Bags + 1x Custom Linen Reagent Bag + First Aid Bandages.", ah30="Convert 30% into Custom Linen Reagent Bags (gray=65) & 6-slot Linen Bags on the AH.", stack="Singles (1 Bag per listing)", margin=310, why="In WoW Forever 1.60.1, Linen Reagent Bags are the #1 Day-1 purchase for every player tired of running out of bag slots." },
  { band="Band 1 (Lv 1-10)", prof="Mining / BS", item="Copper Ore, Bars & Rough Stone", g70="70% smelted by Paladin BS into Rough Sharpening Stones, Copper Chain gear, and 1x Inert Copper Rod for our Banker.", ah30="Convert 30% into Inert Copper Rods (5x Copper Bar + 1x Rough Grinding Stone) + stacks of 10 Copper Bars.", stack="Singles for Rods / Stacks of 10 for Bars", margin=420, why="Solo Enchanters CANNOT make their own Inert Copper Rod—they are forced to buy it from a Blacksmith on the AH!" },
  { band="Band 1 (Lv 1-10)", prof="Herbalism / Alchemy", item="Peacebloom, Silverleaf & Earthroot", g70="70% brewed by Banker Alchemist into Elixir of Lion's Strength, Elixir of Minor Strength, Minor Fortitude & Minor Mana/Healing Potions.", ah30="Sell 30% as Elixir of Minor Strength (pairs of 2!) + Minor Mana Potions + raw Silverleaf stacks.", stack="Stacks of 2 (exactLW Kit qty!) or 5", margin=280, why="Every Leatherworker on WoW Forever needs 2x Elixir of Minor Strength and 2x Minor Mana Potion to craft Forceful/Mystic Medium Armor Kits!" },
  { band="Band 1 (Lv 1-10)", prof="Enchanting", item="Strange Dust & Lesser Magic Essence", g70="70% used by Banker to craft Lesser Magic Wands (Lv 5) for our Mage/Priest/Warlock + supply Strange Dust to our LW.", ah30="Sell 30% as Lesser Magic Wands (Lv 5) + pairs of Strange Dust on the AH.", stack="Singles for Wands / Stacks of 2 or 5 for Dust", margin=350, why="Priests, Mages, and Warlocks desperately buy a Lv 5 Lesser Magic Wand the second they reach the capital city." },
  { band="Band 2 (Lv 10-20)", prof="Skinning / LW", item="Medium Leather & Medium Hides", g70="70% turned into Forceful Medium Armor Kits & Mystic Medium Armor Kits (4 per guild alt = 40 kits).", ah30="Convert 30% into Forceful Medium Armor Kits & Mystic Medium Armor Kits on the AH!", stack="Singles or Sets of 4 (Chest/Hands/Legs/Feet Bundle!)", margin=480, why="99% of players don't have a synchronized Enchanter + Alchemist + Leatherworker trinity—so they pay massive premiums for completed Forceful/Mystic Kits!" },
  { band="Band 2 (Lv 10-20)", prof="Tailoring", item="Wool Cloth & Bolts of Woolen Cloth", g70="70% crafts 8-slot Woolen Bags + Woolen Reagent Bags for the roster and Banker's bank slots.", ah30="Convert 30% into Custom Woolen Reagent Bags (gray=110) & Woolen Bags.", stack="Singles", margin=290, why="Wool drops in a narrow level window (Lv 12-22), making Wool Cloth and Woolen Reagent Bags chronically scarce and overpriced on the AH." },
  { band="Band 2 (Lv 10-20)", prof="Mining / BS / Eng", item="Tin, Silver, Bronze & Coarse Stone", g70="70% crafts Inert Silver Rods, Coarse Sharpening Stones, Bronze Tubes, Flying Tiger Goggles, and Portable Reagent Bots.", ah30="Sell 30% as Inert Silver Rods, Bronze Tubes (Quest item!), and Coarse Stone stacks.", stack="Singles for Rods/Tubes", margin=390, why="Bronze Tubes are required for Duskwood 'Look to the Stars' quests, and Inert Silver Rods are mandatory for Journeyman Enchanters." },
  { band="Band 2 (Lv 10-20)", prof="Herbalism / Alchemy", item="Mageroyal, Briarthorn, Stranglekelp & Swiftthistle", g70="70% brews Swiftness Potions, Elixir of Wisdom, Elixir of Giant Growth, and Lesser Mana Potions.", ah30="Sell 30% as Swiftness Potions, Raw Swiftthistle, and Elixir of Giant Growth (pairs of 2 for LW Heavy Kits!).", stack="Stacks of 2 or 5", margin=360, why="Rogues (Thistle Tea) and PvPers buy Swiftthistle/Swiftness Potions nonstop, while Leatherworkers need 2x Elixir of Giant Growth per Forceful Heavy Kit." },
  { band="Band 3 (Lv 20-30)", prof="Skinning / LW", item="Heavy Leather & Heavy Hides", g70="70% supplies Tailor (for Small Silk Packs!), Blacksmith, Engineer (Repair Bots!), and crafts 4x Forceful/Mystic Heavy Armor Kits per alt.", ah30="Convert 30% into Forceful/Mystic Heavy Armor Kits + Heavy Quivers / Heavy Leather Ammo Pouches.", stack="Singles", margin=410, why="Heavy Leather is the most cross-demanded leather in the game (required by Tailors for Silk Bags, Blacksmiths, and Engineers)." },
  { band="Band 3 (Lv 20-30)", prof="Tailoring", item="Silk Cloth & Bolts of Silk", g70="70% crafts 10-slot Small Silk Packs + Silk Reagent Bags + White Bandit Masks (for DE shuffle).", ah30="Convert 30% into Silk Reagent Bags (gray=140) & Small Silk Packs.", stack="Singles", margin=300, why="Level 20-30 players flood dungeons and immediately buy 10-slot Silk Packs and Silk Reagent Bags." },
  { band="Band 3 (Lv 20-30)", prof="Mining / BS / Eng", item="Iron, Gold, Heavy Stone & Mithril", g70="70% crafts Inert Golden Rods, Heavy Sharpening Stones, Portable Repair Bots (gray=145), Portable Anvils, and Iron Buckles.", ah30="Sell 30% as Deadly Blunderbusses (Ashenvale Quest!), Iron Struts, Gyrochronatoms (Hillsbrad/Badlands Quest!), and Inert Golden Rods.", stack="Singles", margin=450, why="Quest turn-in crafted items (Deadly Blunderbuss, Gyrochronatom, Bronze Tube) sell for 400-600% over material cost to questers." },
  { band="Band 3 (Lv 20-30)", prof="Fishing / Herbalism / Alchemy", item="Oily Blackmouth, Bruiseweed, Kingsblood, Liferoot, Wild Steelbloom", g70="70% brews Free Action Potions, Elixir of Defense, Elixir of Ogre's Strength, and Mana Potions.", ah30="Sell 30% as Free Action Potions, Elixir of Ogre's Strength (used in Forceful Thick Kits!), and Wild Steelbloom.", stack="Stacks of 2 or 5", margin=430, why="Free Action Potions and Wild Steelbloom are liquid gold on any server." },
  { band="Band 4 (Lv 30-40)", prof="Skinning / LW", item="Thick Leather & Cured Thick Hides", g70="70% crafts Forceful/Mystic Thick Armor Kits + Quickdraw Quivers (+13% Ranged Haste) + Thick Ammo Pouches.", ah30="Convert 30% into Forceful/Mystic Thick Armor Kits & Quickdraw Quivers (pays for Level 40 Mounts!).", stack="Singles", margin=460, why="Every Hunter at Level 30 buys a Quickdraw Quiver, and every melee/caster alt wants Forceful/Mystic Thick Armor Kits." },
  { band="Band 4 (Lv 30-40)", prof="Tailoring & Enchanting", item="Mageweave Cloth & Vision Dust", g70="70% crafts 12-slot Mageweave Bags + Mageweave Reagent Bags + White Bandit Masks -> DE into Vision Dust.", ah30="Sell 30% as Mageweave Reagent Bags, Enchanted Mageweave Pouches, and stacks of 5 Vision Dust.", stack="Singles for Bags / Stacks of 5 for Vision Dust", margin=380, why="Vision Dust is required for Forceful/Mystic Thick Armor Kits, Enchanted Mageweave Pouches, Portable Arcane Salvagers, and mid-tier enchants." },
  { band="Band 5-7 (Lv 40-60)", prof="All Artisan Professions", item="Runecloth, Rugged Leather, Thorium, High Herbs, Mooncloth & Transmutes", g70="70% equips the 10-alt roster with 14-28 slot Bags, Bottomless Reagent Bags, Forceful/Mystic Rugged & Core Armor Kits, Pre-BiS gear, and Raid Flasks.", ah30="Liquidate 30% + Daily Cooldowns (2x Alchemy Transmutes + 3x Mooncloth CDs + Cured Rugged Hides + Arcanite Rods + Runecloth/Mooncloth Reagent Bags).", stack="Singles for Bags/Cooldowns / Stacks of 5 for Elixirs", margin=520, why="Passive daily cooldowns alone generate 150-300g per week before counting a single mob drop." },
}

